`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (loop). Reference: golden/reference (gray_mod6__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  wire clk = tb_clk;
  reg reset;
  reg en;
  wire [2:0] gray_out; wire [2:0] ref_gray_out;
  wire [0:0] dir; wire [0:0] ref_dir;
  gray_mod6 dut (.clk(clk), .reset(reset), .en(en), .gray_out(gray_out), .dir(dir));
  gray_mod6__ref ref_i (.clk(clk), .reset(reset), .en(en), .gray_out(ref_gray_out), .dir(ref_dir));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 3; tb_b = tb_b + 1)
      if (ref_gray_out[tb_b] !== 1'bx && ref_gray_out[tb_b] !== 1'bz && gray_out[tb_b] !== ref_gray_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 3;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: gray_out = %h, expected %h", $time, tb_cyc, gray_out, ref_gray_out);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_dir[tb_b] !== 1'bx && ref_dir[tb_b] !== 1'bz && dir[tb_b] !== ref_dir[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: dir = %h, expected %h", $time, tb_cyc, dir, ref_dir);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [2:0] tbc_p_gray_out, tbc_t_gray_out;
  reg [0:0] tbc_p_dir, tbc_t_dir;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_gray_out = tbc_t_gray_out | ((ref_gray_out ^ tbc_p_gray_out) & ~(ref_gray_out ^ ref_gray_out)); tbc_p_gray_out = ref_gray_out;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_dir = tbc_t_dir | ((ref_dir ^ tbc_p_dir) & ~(ref_dir ^ ref_dir)); tbc_p_dir = ref_dir;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_gray_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 3; tb_b = tb_b + 1) if (tbc_t_gray_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_dir) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_dir[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 2 checked outputs toggled, %0d of 4 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 11; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    reset = 0; en = 0; reset = 1;
    tbc_t_gray_out = 0; tbc_p_gray_out = 0; tbc_t_dir = 0; tbc_p_dir = 0;
    for (tb_cyc = 0; tb_cyc < 200; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 400 == 0);
      if (tb_rand(0) % 3 == 0) en = ~en;
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
 `timescale 1ns / 1ps

module gray_mod6__ref(clk, reset, en, gray_out, dir);
	input clk ;
	input reset ;
	input en ;
	output [2:0] gray_out ;
	output dir ;
   supply1 vcc;

	wire [2:0] gray_out ;
	wire dir, x ;
	wire j0, k0, j1, k1, j2, k2 ;
	wire q0, q1, q2, q0_bar, q1_bar, q2_bar,q3_bar ;

	assign j0 = q2_bar & q1_bar ;
	assign k0 = q2_bar & q1 ;
	
	assign j1 = q2_bar & q0 ;
	assign k1 = q0_bar & q2 ;

	assign j2 = q0_bar & q1 ;
	assign k2 = q1_bar & q0_bar ;

	jk_ff jk0(.j(j0), .k(k0), .reset(reset), .en(en), .clk(clk), .q(q0), .qbar(q0_bar));
	jk_ff jk1(.j(j1), .k(k1), .reset(reset), .en(en), .clk(clk), .q(q1), .qbar(q1_bar));
	jk_ff jk2(.j(j2), .k(k2), .reset(reset), .en(en), .clk(clk), .q(q2), .qbar(q2_bar));

	assign gray_out[2] = q2 ;
	assign gray_out[1] = q1 ;
	assign gray_out[0] = q0 ;

	assign x = ((q2 & q1_bar & q0_bar) == 1'b 1) ? 1'b 1 : 1'b 0 ;
	jk_ff jk3(.j(vcc), .k(vcc), .reset(reset), .en(vcc), .clk(! x), .q(dir),.qbar(q3_bar));


endmodule
